const W = 300
const H = 360
const MIN_LON = 88.0
const MAX_LON = 92.8
const MIN_LAT = 20.5
const MAX_LAT = 26.8

export function projectCoordinates(lon: number, lat: number) {
  const x = Math.min(W - 14, Math.max(14, ((lon - MIN_LON) / (MAX_LON - MIN_LON)) * W))
  const y = Math.min(H - 14, Math.max(14, ((MAX_LAT - lat) / (MAX_LAT - MIN_LAT)) * H))
  return { x: Math.round(x * 10) / 10, y: Math.round(y * 10) / 10 }
}

interface BangladeshMapProps {
  latitude: number
  longitude: number
  districtName: string
  divisionName?: string
  lang?: string
}

export function BangladeshMap({
  latitude,
  longitude,
  districtName,
  divisionName,
  lang = 'en',
}: BangladeshMapProps) {
  const { x, y } = projectCoordinates(longitude, latitude)

  return (
    <div className="bd-map-container" aria-label={`Map of Bangladesh highlighting ${districtName}`}>
      <svg
        viewBox={`0 0 ${W} ${H}`}
        className="bd-map-svg"
        role="img"
        aria-hidden="true"
        preserveAspectRatio="xMidYMid meet"
      >
        <defs>
          <filter id="map-drop-shadow" x="-5%" y="-5%" width="115%" height="115%">
            <feDropShadow dx="0" dy="2" stdDeviation="3" floodOpacity="0.1" />
          </filter>
          <radialGradient id="pin-glow" cx="50%" cy="50%" r="50%">
            <stop offset="0%" stopColor="#c25a1c" stopOpacity="0.8" />
            <stop offset="100%" stopColor="#c25a1c" stopOpacity="0" />
          </radialGradient>
        </defs>

        {/* Subtle graticule lines */}
        <g className="bd-map-grid" strokeDasharray="2,3">
          {/* 22°N */}
          <line x1="10" y1={((MAX_LAT - 22.0) / (MAX_LAT - MIN_LAT)) * H} x2="290" y2={((MAX_LAT - 22.0) / (MAX_LAT - MIN_LAT)) * H} />
          {/* 24°N */}
          <line x1="10" y1={((MAX_LAT - 24.0) / (MAX_LAT - MIN_LAT)) * H} x2="290" y2={((MAX_LAT - 24.0) / (MAX_LAT - MIN_LAT)) * H} />
          {/* 26°N */}
          <line x1="10" y1={((MAX_LAT - 26.0) / (MAX_LAT - MIN_LAT)) * H} x2="290" y2={((MAX_LAT - 26.0) / (MAX_LAT - MIN_LAT)) * H} />
          {/* 90°E */}
          <line x1={((90.0 - MIN_LON) / (MAX_LON - MIN_LON)) * W} y1="10" x2={((90.0 - MIN_LON) / (MAX_LON - MIN_LON)) * W} y2="350" />
          {/* 92°E */}
          <line x1={((92.0 - MIN_LON) / (MAX_LON - MIN_LON)) * W} y1="10" x2={((92.0 - MIN_LON) / (MAX_LON - MIN_LON)) * W} y2="350" />
        </g>

        {/* Bangladesh outline */}
        <path
          d={BD_OUTLINE_PATH}
          className="bd-map-country"
          filter="url(#map-drop-shadow)"
        />

        {/* Bay of Bengal label */}
        <text x="110" y="340" className="bd-map-water-label">
          {lang === 'bn' ? 'বঙ্গোপসাগর' : 'Bay of Bengal'}
        </text>

        {/* Grid coordinates labels */}
        <text x="272" y={((MAX_LAT - 24.0) / (MAX_LAT - MIN_LAT)) * H - 3} className="bd-map-coord-label">24°N</text>
        <text x={((90.0 - MIN_LON) / (MAX_LON - MIN_LON)) * W + 3} y="22" className="bd-map-coord-label">90°E</text>

        {/* Compass indicator */}
        <g className="bd-map-compass" transform="translate(268, 32)">
          <circle cx="0" cy="0" r="10" className="compass-ring" />
          <polygon points="0,-7 3,0 0,-2 -3,0" fill="#136248" />
          <polygon points="0,7 3,0 0,2 -3,0" fill="#999" />
          <text x="0" y="-10" textAnchor="middle" className="compass-text">N</text>
        </g>

        {/* District location marker */}
        <g className="bd-map-marker" transform={`translate(${x}, ${y})`}>
          {/* Pulsing halo */}
          <circle r="14" className="pin-pulse" />
          <circle r="8" fill="url(#pin-glow)" />
          {/* Center pinpoint */}
          <circle r="4.5" className="pin-dot" />
          <circle r="2" fill="#fff" />

          {/* District label badge */}
          <g transform="translate(0, -14)">
            <rect
              x="-48"
              y="-18"
              width="96"
              height="20"
              rx="4"
              className="pin-tag-bg"
            />
            <text x="0" y="-4" textAnchor="middle" className="pin-tag-text">
              {districtName}
            </text>
          </g>
        </g>
      </svg>
      <div className="bd-map-meta">
        <span className="bd-map-meta-loc">
          📍 {districtName}{divisionName ? ` · ${divisionName}` : ''}
        </span>
        <span className="bd-map-meta-coords">
          {latitude.toFixed(2)}° N, {longitude.toFixed(2)}° E
        </span>
      </div>
    </div>
  )
}
